1	package org.springframework.samples.petclinic.mapper;
2	
3	import org.jspecify.annotations.NonNull;
4	import org.mapstruct.Mapper;
5	import org.mapstruct.Mapping;
6	import org.springframework.beans.factory.annotation.Autowired;
7	import org.springframework.data.domain.Page;
8	import org.springframework.samples.petclinic.model.Owner;
9	import org.springframework.samples.petclinic.rest.controller.CityRegionResolver;
10	import org.springframework.samples.petclinic.rest.controller.TelephoneNormalizer;
11	import org.springframework.samples.petclinic.rest.dto.OwnerDto;
12	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
13	import org.springframework.samples.petclinic.rest.dto.OwnerPageDto;
14	import org.springframework.samples.petclinic.service.ClinicService;
15	import org.springframework.samples.petclinic.util.HashUtils;
16	import org.springframework.samples.petclinic.util.IdentityUtils;
17	
18	import java.time.LocalDate;
19	import java.time.Month;
20	import java.time.Period;
21	import java.util.Collection;
22	import java.util.List;
23	import java.util.Locale;
24	import java.util.OptionalInt;
25	
26	/**
27	 * Maps Owner & OwnerDto using Mapstruct
28	 */
29	@Mapper(uses = PetMapper.class)
30	public abstract class OwnerMapper {
31	
32	    /** Used to count the members of an owner's household when deriving derived fields. */
33	    @Autowired
34	    protected ClinicService clinicService;
35	
36	    /** Single source of truth for the city-to-region mapping behind an owner's locality. */
37	    @Autowired
38	    protected CityRegionResolver cityRegionResolver;
39	
40	    /** Formats the stored E.164 telephone into its human-readable display form. */
41	    @Autowired
42	    protected TelephoneNormalizer telephoneNormalizer;
43	
44	    @Mapping(target = "selfLink", expression = "java(selfLink(owner))")
45	    @Mapping(target = "salutation", expression = "java(salutation(owner))")
46	    @Mapping(target = "displayName",
47	        expression = "java(owner.getLastName() + \", \" + owner.getFirstName())")
48	    @Mapping(target = "initials", expression = "java(initials(owner))")
49	    @Mapping(target = "membershipPoints", expression = "java(membershipPoints(owner))")
50	    @Mapping(target = "membershipLevel", expression = "java(membershipLevel(owner))")
51	    @Mapping(target = "locality", expression = "java(locality(owner))")
52	    @Mapping(target = "timezone", expression = "java(timezone(owner))")
53	    @Mapping(target = "contactPreference", expression = "java(contactPreference(owner))")
54	    @Mapping(target = "telephoneDisplay", expression = "java(telephoneNormalizer.toDisplayForm(owner.getTelephone()))")
55	    @Mapping(target = "identityKey", expression = "java(identityKey(owner))")
56	    @Mapping(target = "checkDigit", expression = "java(checkDigit(owner))")
57	    @Mapping(target = "ageBand", expression = "java(ageBand(owner))")
58	    @Mapping(target = "fiscalYear", expression = "java(fiscalYear(owner))")
59	    public abstract OwnerDto toOwnerDto(Owner owner);
60	
61	    /**
62	     * The owner's self link: '/api/owners/' followed by the owner's id, or null when the
63	     * owner has no id assigned yet.
64	     */
65	    String selfLink(Owner owner) {
66	        return owner.getId() == null ? null : "/api/owners/" + owner.getId();
67	    }
68	
69	    /**
70	     * The fiscal year (starting 1 July) that {@code date} falls in, identified by the
71	     * calendar year in which the fiscal year ends: a date in July–December belongs to the
72	     * fiscal year ending the following calendar year, while January–June belongs to the one
73	     * ending that same calendar year.
74	     */
75	    public static int fiscalYear(LocalDate date) {
76	        return date.getMonthValue() >= Month.JULY.getValue() ? date.getYear() + 1 : date.getYear();
77	    }
78	
79	    /**
80	     * The owner's fiscal year formatted 'FY<YY>', where YY is the last two digits of the
81	     * fiscal year of the (business-day-adjusted) {@code registrationDate} and the fiscal year
82	     * starts on 1 July. Returns null when no registrationDate has been assigned.
83	     */
84	    String fiscalYear(Owner owner) {
85	        LocalDate registrationDate = owner.getRegistrationDate();
86	        if (registrationDate == null) {
87	            return null;
88	        }
89	        return String.format("FY%02d", fiscalYear(registrationDate) % 100);
90	    }
91	
92	    /**
93	     * The owner's age band derived from {@code birthDate} relative to the
94	     * {@code registrationDate}: 'MINOR' when under 18, 'ADULT' from 18 to 64
95	     * inclusive and 'SENIOR' at 65 or older. Returns null when either date is
96	     * absent so no band can be computed.
97	     */
98	    OwnerDto.AgeBandEnum ageBand(Owner owner) {
99	        LocalDate birthDate = owner.getBirthDate();
100	        LocalDate registrationDate = owner.getRegistrationDate();
101	        if (birthDate == null || registrationDate == null) {
102	            return null;
103	        }
104	        int age = Period.between(birthDate, registrationDate).getYears();
105	        if (age < 18) {
106	            return OwnerDto.AgeBandEnum.MINOR;
107	        }
108	        if (age < 65) {
109	            return OwnerDto.AgeBandEnum.ADULT;
110	        }
111	        return OwnerDto.AgeBandEnum.SENIOR;
112	    }
113	
114	    /**
115	     * The owner's check digit: a single Luhn check digit (0-9) computed over the digits
116	     * contained in the customerCode, or null when no customerCode has been assigned.
117	     */
118	    Integer checkDigit(Owner owner) {
119	        String customerCode = owner.getCustomerCode();
120	        return customerCode == null ? null : luhn(customerCode);
121	    }
122	
123	    /**
124	     * The Luhn check digit (0-9) over the digits contained in {@code s}: from the rightmost
125	     * digit leftward, every second digit is doubled (the rightmost first) with digits over 9
126	     * reduced by 9, and the check digit makes the total a multiple of ten.
127	     */
128	    static int luhn(String s) {
129	        int sum = 0;
130	        boolean doubling = true;
131	        for (int i = s.length() - 1; i >= 0; i--) {
132	            char c = s.charAt(i);
133	            if (c < '0' || c > '9') {
134	                continue;
135	            }
136	            int d = c - '0';
137	            if (doubling) {
138	                d *= 2;
139	                if (d > 9) {
140	                    d -= 9;
141	                }
142	            }
143	            sum += d;
144	            doubling = !doubling;
145	        }
146	        return (10 - (sum % 10)) % 10;
147	    }
148	
149	    /**
150	     * The owner's derived identity key: the SHA-256 hex digest of the normalized telephone,
151	     * the lower-cased email (or an empty string when absent) and the {@link IdentityUtils#soundex
152	     * soundex} of the last name, joined by '|'. This single key is the sole basis for duplicate
153	     * detection on create — two owners are duplicates only when their whole identityKey matches,
154	     * so two people sharing a household (a like-sounding last name and postcode) but carrying
155	     * different telephones derive different keys and are all permitted.
156	     */
157	    public static String identityKey(Owner owner) {
158	        String telephone = owner.getTelephone() == null ? "" : owner.getTelephone();
159	        String email = owner.getEmail() == null ? "" : owner.getEmail().toLowerCase(Locale.ROOT);
160	        String lastNameSoundex = IdentityUtils.soundex(owner.getLastName());
161	        return HashUtils.sha256Hex(telephone + "|" + email + "|" + lastNameSoundex);
162	    }
163	
164	    /**
165	     * The owner's preferred contact channel: 'EMAIL' when an email address is
166	     * present, otherwise 'PHONE'.
167	     */
168	    String contactPreference(Owner owner) {
169	        boolean hasEmail = owner.getEmail() != null && !owner.getEmail().isBlank();
170	        return hasEmail ? "EMAIL" : "PHONE";
171	    }
172	
173	    /**
174	     * The owner's locality: the REGION component of the customerCode identity (the part before
175	     * the first '-' of {@code '<REGION>-<HASH8>'}). When no customerCode has been assigned this
176	     * falls back to the canonical region derived from the owner via {@link CityRegionResolver},
177	     * preferring the postcode over the city, or 'UNKNOWN' when neither yields a known region.
178	     */
179	    String locality(Owner owner) {
180	        String customerCode = owner.getCustomerCode();
181	        if (customerCode != null) {
182	            int dash = customerCode.indexOf('-');
183	            if (dash >= 0) {
184	                return customerCode.substring(0, dash);
185	            }
186	        }
187	        return cityRegionResolver.regionFor(owner.getCity(), owner.getPostcode());
188	    }
189	
190	    /**
191	     * The owner's IANA timezone name derived from the owner's {@link #locality(Owner) locality}
192	     * via the fixed region-to-timezone table (NSW -> Australia/Sydney, VIC -> Australia/Melbourne,
193	     * QLD -> Australia/Brisbane). Returns null when the locality is not a region in the table.
194	     */
195	    String timezone(Owner owner) {
196	        return cityRegionResolver.timezoneForRegion(locality(owner));
197	    }
198	
199	    /**
200	     * The owner's membership points: starting at 0, plus 2 when an email address is present,
201	     * plus 1 when namesakeCount is 0, plus 2 for a household of 3 or more members, plus 3 when
202	     * the owner's tenure is more than one fiscal year.
203	     */
204	    public int membershipPoints(Owner owner) {
205	        int points = 0;
206	        boolean hasEmail = owner.getEmail() != null && !owner.getEmail().isBlank();
207	        if (hasEmail) {
208	            points += 2;
209	        }
210	        boolean uniqueName = owner.getNamesakeCount() != null && owner.getNamesakeCount() == 0;
211	        if (uniqueName) {
212	            points += 1;
213	        }
214	        if (householdSize(owner) >= 3) {
215	            points += 2;
216	        }
217	        LocalDate registrationDate = owner.getRegistrationDate();
218	        boolean tenured = registrationDate != null
219	            && fiscalYear(LocalDate.now()) - fiscalYear(registrationDate) > 1;
220	        if (tenured) {
221	            points += 3;
222	        }
223	        return points;
224	    }
225	
226	    /**
227	     * The owner's numeric membership level from 1 to 4, derived from {@link #membershipPoints}
228	     * via {@link #levelForPoints} and then held to the household level-ceiling by
229	     * {@link #cappedByHousehold}.
230	     */
231	    public int membershipLevel(Owner owner) {
232	        return cappedByHousehold(owner, levelForPoints(membershipPoints(owner)));
233	    }
234	
235	    /**
236	     * Hold {@code level} to the household level-ceiling: an owner's membershipLevel may not exceed
237	     * one above the current maximum membershipLevel among the household members that already
238	     * existed when this owner registered — the other, non-deleted owners sharing its householdId
239	     * that were created earlier (a strictly lower id, ids being monotonic). When no such earlier
240	     * household member exists no ceiling applies and {@code level} is returned unchanged.
241	     *
242	     * @param owner the owner whose own level is being capped
243	     * @param level the owner's uncapped membership level
244	     * @return the level, capped at one above the earlier household members' maximum
245	     */
246	    private int cappedByHousehold(Owner owner, int level) {
247	        Integer id = owner.getId();
248	        String householdId = owner.getHouseholdId();
249	        if (id == null || householdId == null) {
250	            return level;
251	        }
252	        OptionalInt maxExisting = clinicService.findAllOwners().stream()
253	            .filter(existing -> !existing.isDeleted())
254	            .filter(existing -> existing.getId() != null && existing.getId() < id)
255	            .filter(existing -> householdId.equals(existing.getHouseholdId()))
256	            .mapToInt(this::membershipLevel)
257	            .max();
258	        return maxExisting.isEmpty() ? level : Math.min(level, maxExisting.getAsInt() + 1);
259	    }
260	
261	    /**
262	     * The numeric membership level from 1 to 4 that {@code points} maps to: level 1 for 0-1
263	     * points, level 2 for 2-3 points, level 3 for 4-5 points and level 4 for 6 or more points.
264	     */
265	    int levelForPoints(int points) {
266	        if (points >= 6) {
267	            return 4;
268	        }
269	        if (points >= 4) {
270	            return 3;
271	        }
272	        if (points >= 2) {
273	            return 2;
274	        }
275	        return 1;
276	    }
277	
278	    /**
279	     * The owners belonging to {@code owner}'s household, i.e. those sharing its householdId
280	     * (including the owner itself once persisted). Returns an empty list when the owner has no
281	     * household id assigned.
282	     */
283	    List<Owner> householdMembers(Owner owner) {
284	        String householdId = owner.getHouseholdId();
285	        if (householdId == null) {
286	            return List.of();
287	        }
288	        return clinicService.findAllOwners().stream()
289	            .filter(existing -> householdId.equals(existing.getHouseholdId()))
290	            .toList();
291	    }
292	
293	    /**
294	     * The number of owners belonging to {@code owner}'s household, i.e. those sharing its
295	     * householdId (including the owner itself once persisted). Returns 0 when the owner has no
296	     * household id assigned.
297	     */
298	    int householdSize(Owner owner) {
299	        return householdMembers(owner).size();
300	    }
301	
302	    /**
303	     * The owner's salutation: the {@code title} and last name separated by a single space
304	     * (e.g. 'DR who'), or just the last name when no title has been supplied.
305	     */
306	    String salutation(Owner owner) {
307	        String title = owner.getTitle();
308	        if (title == null || title.isBlank()) {
309	            return owner.getLastName();
310	        }
311	        return title + " " + owner.getLastName();
312	    }
313	
314	    /**
315	     * The upper-cased first letters of firstName and lastName, dot-separated with a
316	     * trailing dot, e.g. 'J.S.'.
317	     */
318	    String initials(Owner owner) {
319	        return Character.toUpperCase(owner.getFirstName().charAt(0)) + "."
320	            + Character.toUpperCase(owner.getLastName().charAt(0)) + ".";
321	    }
322	
323	    public abstract Owner toOwner(OwnerDto ownerDto);
324	
325	    @Mapping(target = "id", ignore = true)
326	    @Mapping(target = "pets", ignore = true)
327	    public abstract Owner toOwner(OwnerFieldsDto ownerDto);
328	
329	    public abstract List<OwnerDto> toOwnerDtoCollection(Collection<Owner> ownerCollection);
330	
331	    public abstract Collection<Owner> toOwners(Collection<OwnerDto> ownerDtos);
332	
333	    public OwnerPageDto toOwnerPageDto(@NonNull Page<Owner> ownerPage) {
334	        OwnerPageDto ownerPageDto = new OwnerPageDto();
335	        ownerPageDto.setContent(toOwnerDtoCollection(ownerPage.getContent()));
336	        ownerPageDto.setPage(ownerPage.getNumber());
337	        ownerPageDto.setSize(ownerPage.getSize());
338	        ownerPageDto.setTotalElements(ownerPage.getTotalElements());
339	        ownerPageDto.setTotalPages(ownerPage.getTotalPages());
340	        return ownerPageDto;
341	    }
342	}
